"""symchk.py n sizes: every graph on n vertices has an image under the group generated by
permutations inside parts and swaps of equal parts that satisfies the symmetry-breaking clauses
(lex inside parts and flag s) of scripts/stab2.py, taken from its own clause list."""
import sys, itertools, runpy, io, contextlib, os, tempfile
from pysat.solvers import Minisat22
n = int(sys.argv[1]); sizes = sys.argv[2]; p = len(sizes.split(','))
out = os.path.join(tempfile.mkdtemp(), 'x.cnf')
sys.argv = ['stab2.py', str(n), str(p), sizes, out, '0', '-', 's']
with contextlib.redirect_stderr(io.StringIO()):
    g = runpy.run_path(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'stab2.py'))
pool, cls, pairs, P = g['pool'], g['cls'], g['pairs'], g['P']
Evar = {pool.id(('E', a, b)): (a, b) for a, b in pairs}
aux = set(v for k, v in pool.obj2id.items() if k[0] in ('eq', 'seq'))
sb = [c for c in cls if all(abs(x) in Evar or abs(x) in aux for x in c) and any(abs(x) in aux for x in c)]
print('symmetry clauses', len(sb))
# the group
parts = [list(Q) for Q in P]
def perms():
    eqpairs = [(i, j) for i, j in itertools.combinations(range(p), 2) if len(parts[i]) == len(parts[j])]
    # all permutations of part labels among equal sizes, composed with permutations inside parts
    labelperms = [q for q in itertools.permutations(range(p)) if all(len(parts[q[i]]) == len(parts[i]) for i in range(p))]
    for q in labelperms:
        for inner in itertools.product(*[itertools.permutations(range(len(parts[i]))) for i in range(p)]):
            sig = [0] * n
            for i in range(p):
                for k, v in enumerate(parts[i]): sig[v] = parts[q[i]][inner[i][k]]
            yield sig
G = list(perms()); print('group order', len(G))
s = Minisat22(bootstrap_with=sb); bad = 0
for mask in range(1 << len(pairs)):
    edges = [pairs[k] for k in range(len(pairs)) if mask >> k & 1]
    ok = False
    for sig in G:
        im = set(tuple(sorted((sig[a], sig[b]))) for a, b in edges)
        assum = [v if Evar[v] in im else -v for v in Evar]
        if s.solve(assumptions=assum): ok = True; break
    if not ok: bad += 1
print('graphs', 1 << len(pairs), 'without a good image', bad)
